# Раскадровка «Что если бы вы родились в Северной Корее?» → build.py
# X('слово') — привязка к слову озвучки, T(сек) — абсолютное время. Помощники: sc, FACE, BIG, SPL, MAP, NK.
from kit import S, A, P, G, card, B

def sc(set, cast=(), props=(), tags=(), cam=None, o=None, **kw): return S(set, cast, props, tags, cam, setOpts=o or {}, **kw)
def z(x, y, z0=1.0, z1=1.15): return [[0, x, y, z0], ['end', x, y, z1]]
def pan(x0, y0, x1, y1, z0=1.1, z1=1.2): return [[0, x0, y0, z0], ['end', x1, y1, z1]]
def FACE(c, set='plain', expr='neutral', x=960, s=1.0, zz=2.4, tags=(), props=(), o=None, **a):
    hy = 930 - 240 * s
    return S(set, [A(c, x, 930, s=s, expr=expr, **a)], list(props), list(tags), [[0, x, hy + 40, zz], ['end', x, hy + 30, zz * 1.08]], setOpts=o or {})
def BIG(text, sub=None, set='black', col='#ffffff', props=(), size=170, dim=None, o=None, y=None, **kw):
    b = dict(t=text, size=size, col=col, at=0.05)
    if sub: b['sub'] = sub
    if y: b['y'] = y
    extra = dict(dim=dim) if dim else {}
    return S(set, [], list(props), [], None, big=[b], setOpts=o or {}, **extra, **kw)
def half(set, cast=(), props=(), tags=(), o=None): return dict(set=set, cast=list(cast), props=list(props), tags=list(tags), setOpts=o or {})
def SPL(L, R): return ('split', dict(L=L, R=R))
def MAP(view=(118, 33, 134, 44), hl=None, style='paper', push=1.1, cam=None, tags=(), big=None, **o):
    o.update(view=list(view), hl=hl or {}, style=style); kw = dict(push=push)
    if big: kw['big'] = big
    return S('world', [], [], list(tags), cam, setOpts=o, **kw)
def NK(cam=None, tags=(), props=(), f=None, **o):
    if f: o['focus'] = list(f)
    return S('nightKorea', [], list(props), list(tags), cam or (z(960, 540, 1.0, 1.02) if f else z(960, 540, 1.0, 1.12)), setOpts=o)
